#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include "owned_session_ik_pass.h"
#include <iostream>
void sameGraph(const Graph&a,const Graph&b){if(a.header!=b.header||a.strings!=b.strings||a.elements.size()!=b.elements.size())throw std::runtime_error("graph mismatch");for(size_t i=0;i<a.elements.size();++i){const auto&x=a.elements[i];const auto&y=b.elements[i];if(x.type!=y.type||x.name!=y.name||x.id!=y.id||x.attributes.size()!=y.attributes.size())throw std::runtime_error("element mismatch");for(size_t j=0;j<x.attributes.size();++j){const auto&u=x.attributes[j];const auto&v=y.attributes[j];if(u.name!=v.name||u.type!=v.type||u.values.size()!=v.values.size())throw std::runtime_error("attribute mismatch");for(size_t k=0;k<u.values.size();++k){const auto&p=u.values[k];const auto&q=v.values[k];if(p.wire!=q.wire||p.reference!=q.reference||p.text!=q.text||p.stringIndex!=q.stringIndex)throw std::runtime_error("value mismatch");}}}}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("input fresh output required");auto original=loadGraph(argv[1]);RecoveredOwnedDmxReferenceProjectionCandidate<Graph>p(original,[](const std::string&,auto&)->uint32_t{throw std::runtime_error("external resolver");});auto select=[](uint32_t){return std::array<uint32_t,3>{0xffffffffu,0xffffffffu,0xffffffffu};};auto result=executeOwnedSessionIkPassCandidate(p,select,0,true);if(result.undoRecords.size()!=result.changes.attributes.size())throw std::runtime_error("history journal mismatch");auto after=p.graph;for(unsigned cycle=0;cycle<4;++cycle){if(replayOwnedIkUndoRecordsCandidate(p,result.undoRecords,true)!=result.undoRecords.size())throw std::runtime_error("undo dispatch");sameGraph(original,p.graph);if(replayOwnedIkUndoRecordsCandidate(p,result.undoRecords,false)!=result.undoRecords.size())throw std::runtime_error("redo dispatch");sameGraph(after,p.graph);}auto blocked=executeOwnedSessionIkPassCandidate(p,select,3,true);if(!blocked.undoRecords.empty()||!blocked.changes.attributes.empty())throw std::runtime_error("blocked edits recorded");sameGraph(after,p.graph);auto exported=p.exportReferences([](uint32_t,const auto&)->std::string{throw std::runtime_error("external export");});saveGraph(exported,argv[2]);auto reload=loadGraph(argv[2]);sameGraph(after,reload);p.scene.cleanup({},[](auto&,bool){},[](auto&){});if(replayOwnedIkUndoRecordsCandidate(p,result.undoRecords,true)||p.scene.size()||p.scene.attributes.size()||p.scene.references.nodes.allocationCount())throw std::runtime_error("stale history teardown");std::cout<<"ik_operators="<<result.executed<<" undo_records="<<result.undoRecords.size()<<" full_graph_undo_redo_cycles=4 blocked_history_reload_stale_teardown=passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
